from openpyxl import load_workbook
src='/root/data/workbook.xlsx'
out='/root/output/result.xlsx'
orig=load_workbook(src, data_only=False, read_only=True)
wb=load_workbook(out, data_only=False)
ws=wb['Task']
errors=[]
if wb.sheetnames != orig.sheetnames:
    errors.append(f'sheet names changed: {wb.sheetnames} != {orig.sheetnames}')
for addr in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','L47','H50','L50']:
    v=ws[addr].value
    if not (isinstance(v,str) and v.startswith('=')):
        errors.append(f'{addr} does not contain formula string: {v!r}')
# Count all required formula cells.
required=[]
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            required.append(ws.cell(r,c).coordinate)
missing=[addr for addr in required if not (isinstance(ws[addr].value,str) and ws[addr].value.startswith('='))]
if missing:
    errors.append(f'missing formulas in {len(missing)} cells: {missing[:20]}')
# Verify exact formulas for representative cells.
expected={
'H12':'=INDEX(Data!$H$21:$L$38,MATCH($D12,Data!$D$21:$D$38,0),MATCH(H$10,Data!$H$4:$L$4,0))',
'L31':'=INDEX(Data!$H$21:$L$38,MATCH($D31,Data!$D$21:$D$38,0),MATCH(L$10,Data!$H$4:$L$4,0))',
'H35':'=(H12-H19)/H26*100',
'L40':'=(L17-L24)/L31*100',
'H42':'=MIN(H$35:H$40)',
'L47':'=PERCENTILE.INC(L$35:L$40,0.75)',
'H50':'=SUMPRODUCT(H$35:H$40,H$26:H$31)/SUM(H$26:H$31)',
'L50':'=SUMPRODUCT(L$35:L$40,L$26:L$31)/SUM(L$26:L$31)',
}
for addr, exp in expected.items():
    if ws[addr].value != exp:
        errors.append(f'{addr}: expected {exp!r}, got {ws[addr].value!r}')
print('Original sheets:', orig.sheetnames)
print('Result sheets:', wb.sheetnames)
print('Required formula cells checked:', len(required))
for addr in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','L47','H50','L50']:
    print(addr, ws[addr].value)
if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('-', e)
    raise SystemExit(1)
print('VALIDATION PASSED')
